examples.template:
MonarchPasskeyManager(
    passkeys = passkeys,
    title = {{title}},
    passkeyIcon = { MonarchIcon(SampleIcons.Key, contentDescription = null) },
    description = {{description}},
    now = {{now|millis}},
    onAdd = {
        // The app calls CredentialManager.createCredential with its server's challenge here,
        // returns false on CreateCredentialCancellationException, and reloads the list.
        true
    },
    onRemove = { id -> passkeys = passkeys.filterNot { it.id == id } },
)

examples.setupTemplate:
var passkeys by remember {
    mutableStateOf(
        listOf(
            MonarchPasskey(
                id = {{passkeys.0.id}},
                name = {{passkeys.0.name}},
                createdMillis = {{passkeys.0.createdAt|millis}},
                lastUsedMillis = {{passkeys.0.lastUsedAt|millis}},
                synced = {{passkeys.0.synced}},
            ),
            MonarchPasskey(
                id = {{passkeys.1.id}},
                name = {{passkeys.1.name}},
                createdMillis = {{passkeys.1.createdAt|millis}},
            ),
        ),
    )
}

examples.setup:
